const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let UNIT=localStorage.getItem('kv_unit')||'TODOS', MOD='dashboard', ME=null;
const icons={dashboard:'⌂',services:'🔧',devices:'📱',purchases:'🛒',unlock:'🔓',pdv:'▣',pricing:'💲',quotes:'🧾',finance:'💰',inventory:'📦',forgotten:'🗃️',customers:'👥',contracts:'📜',users:'👤',chat:'💬',chat_units:'↔',ai:'🤖',logs:'☷',admin:'🛡️',settings:'⚙️'};
const names={dashboard:'Painel',services:'Consertos / OS',devices:'Aparelhos',purchases:'Compras',unlock:'Desbloqueios',pdv:'PDV',pricing:'Precificação',quotes:'Orçamentos',finance:'Financeiro',inventory:'Estoque',forgotten:'Esquecidos',customers:'Clientes',contracts:'Termos',users:'Usuários',chat:'Chat',chat_units:'Unidades',ai:'I.A.',logs:'Logs',admin:'Administração',settings:'Configurações'};
async function api(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d;try{d=await r.json()}catch{d={}}if(r.status===401){showLogin();throw Error('Sessão expirada')}if(!r.ok){const msg=d.reply||d.error||'Erro';throw Error(msg)}return d}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function showLogin(){document.body.innerHTML=`<div class="login"><div class="login-card"><div class="login-logo">KV</div><h1>KV CELL OS PREMIUM</h1><p>Gestão completa da assistência técnica • Lagos + Magé</p><form id="lf"><div class="field"><label>E-mail</label><input class="input" name="email" autocomplete="username"></div><div class="field"><label>Senha</label><input class="input" name="password" type="password" autocomplete="current-password"></div><button class="btn">Entrar no sistema</button></form><p style="margin-top:16px" class="muted">Credenciais definidas pelo administrador.</p></div></div>`;$('#lf').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/login',{method:'POST',body:JSON.stringify(formValues(e.target))});ME=d.user;boot()}catch(x){toast(x.message)}}}
function boot(){document.body.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="logo">KV</div><div><b>KV CELL</b><small>OS PREMIUM • 2026</small></div></div><div class="nav"><div class="navtitle">OPERAÇÃO</div>${['dashboard','services','devices','purchases','unlock','pdv'].map(m=>nav(m)).join('')}<div class="navtitle">GESTÃO</div>${['pricing','quotes','finance','inventory','forgotten','customers','contracts'].map(m=>nav(m)).join('')}<div class="navtitle">ADMIN</div>${['users','chat','admin','settings'].map(m=>nav(m)).join('')}</div></aside><main class="main"><div class="topbar"><div><b id="crumb">Painel</b><div class="crumb">KV CELL OS PREMIUM • controle da operação</div></div><div class="top-actions"><select id="unit" class="select unit"><option>TODOS</option><option>LAGOS</option><option>MAGÉ</option></select><button class="btn ghost" onclick="openSearch()">⌕ Buscar</button><button class="btn ghost" onclick="logout()">Sair</button></div></div><div id="content"></div></main></div><div id="modal" class="modal"></div><div id="toast" class="toast"></div>`;$('#unit').value=UNIT;$('#unit').onchange=e=>{UNIT=e.target.value;localStorage.setItem('kv_unit',UNIT);render()};render()}
function nav(m){return `<button id="nav-${m}" onclick="go('${m}')"><span class="ico">${icons[m]}</span><span>${names[m]}</span></button>`}
function go(m){MOD=m;render()}
async function render(){if(!ME)return showLogin();$$('.nav button').forEach(x=>x.classList.remove('active'));$('#nav-'+MOD)?.classList.add('active');$('#crumb').textContent=names[MOD];let fn=pages[MOD]||pages.dashboard;await fn()}
function money(n){return 'R$ '+Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function badge(v){let x=String(v||'');let cls=/pronto|entregue|vitrine|aberto/i.test(x)?'g':/cancel|baixo/i.test(x)?'r':'y';return `<span class="badge ${cls}">${esc(x||'-')}</span>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function list(t){return api('/api/'+t+'?unit='+encodeURIComponent(UNIT))}
function table(data,cols,actions=''){if(!data.length)return `<div class="empty">Nenhum registro encontrado.<br><small>Use o botão + Novo para começar.</small></div>`;return `<div class="table-wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}${actions?'<th>Ações</th>':''}</tr></thead><tbody>${data.map(r=>`<tr>${cols.map(c=>`<td>${c[2]?c[2](r):esc(r[c[0]])}</td>`).join('')}${actions?`<td>${actions(r)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function head(title,desc,buttons=''){return `<div class="page-title"><div><h1>${title}</h1><p>${desc}</p></div><div class="toolbar">${buttons}</div></div>`}
const pages={
 dashboard:async()=>{let [s,c]=await Promise.all([api('/api/dashboard?unit='+UNIT),api('/api/chart?unit='+UNIT)]);let max=Math.max(1,...c.map(x=>Math.max(x.income,x.expense)));$('#content').innerHTML=head('Painel','Visão geral da operação • filtro global: '+UNIT)+`<div class="cards"><div class="metric"><div class="label">RECEITAS</div><div class="value green">${money(s.income)}</div><div class="sub">Entradas registradas</div></div><div class="metric"><div class="label">DESPESAS</div><div class="value red">${money(s.expense)}</div><div class="sub">Saídas registradas</div></div><div class="metric"><div class="label">SALDO</div><div class="value yellow">${money(s.income-s.expense)}</div><div class="sub">Resultado financeiro</div></div><div class="metric"><div class="label">CONSERTO / OS</div><div class="value">${s.open_services}</div><div class="sub">Em aberto / andamento</div></div><div class="metric"><div class="label">APARELHOS VITRINE</div><div class="value">${s.vitrine}</div><div class="sub">Prontos para venda</div></div><div class="metric"><div class="label">ESTOQUE BAIXO</div><div class="value ${s.low_stock?'red':''}">${s.low_stock}</div><div class="sub">Precisam reposição</div></div><div class="metric"><div class="label">CLIENTES</div><div class="value">${s.customers}</div><div class="sub">Base cadastrada</div></div><div class="metric"><div class="label">VENDAS</div><div class="value">${s.sales}</div><div class="sub">Registros de venda</div></div></div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Fluxo financeiro • últimos 14 dias</h2><div class="legend"><span><i class="dot" style="background:#ffd400"></i> Entradas</span><span><i class="dot" style="background:#ff5c68"></i> Saídas</span></div></div><div class="chart">${c.map(x=>`<div class="barcol"><div class="bar in" style="height:${Math.max(2,x.income/max*180)}px"></div><div class="bar out" style="height:${Math.max(2,x.expense/max*180)}px"></div><small>${x.date}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Ações rápidas</h2></div><div class="quick"><button onclick="go('services')"><b>+ Nova OS</b>Registrar conserto</button><button onclick="go('quotes')"><b>+ Orçamento</b>Enviar link ao cliente</button><button onclick="go('purchases')"><b>+ Compra</b>Entrada de aparelho</button><button onclick="go('pdv')"><b>+ Venda</b>Registrar no caixa</button></div><div style="margin-top:18px"><div class="kpi"><span>Unidade selecionada</span><b class="yellow">${UNIT}</b></div><div class="kpi"><span>Sistema</span><b class="green">ONLINE</b></div></div></section></div>`},
 customers:async()=>{let d=await list('customers');$('#content').innerHTML=head('Clientes','Cadastro completo PF/PJ, documentos, contato, endereço e aniversário',`<button class="btn" onclick="customerForm()">+ Novo cliente</button>`)+table(d,[['id','#'],['type','Tipo'],['name','Nome'],['document','CPF/CNPJ'],['phone','Telefone'],['city','Cidade'],['balance','Saldo',r=>money(r.balance)],['created_at','Cadastro']])},
 devices:async()=>{let d=await list('devices');$('#content').innerHTML=head('Aparelhos','Ficha técnica, IMEI, status e fotos',`<button class="btn" onclick="deviceForm()">+ Novo aparelho</button>`)+table(d,[['id','#'],['unit','Unidade'],['brand','Marca'],['model','Modelo'],['imei','IMEI'],['storage','Memória'],['status','Status',r=>badge(r.status)]],r=>`<button class="btn ghost" onclick="quickPhotos('devices',${r.id},${JSON.stringify(JSON.parse(r.photos||'[]'))})">📷 Fotos</button>`)},
 services:async()=>{let d=await list('services');$('#content').innerHTML=head('Consertos / Ordens de Serviço','Acompanhe cada aparelho desde a entrada até a entrega',`<button class="btn" onclick="serviceForm('conserto')">+ Nova OS</button>`)+table(d,[['id','OS'],['unit','Unidade'],['kind','Tipo'],['description','Serviço'],['technician','Técnico'],['price','Valor',r=>money(r.price)],['status','Status',r=>badge(r.status)],['created_at','Entrada']],r=>`<button class="btn ghost" onclick="serviceDetails(${r.id})">Abrir</button>`)},
 unlock:async()=>{let d=await list('unlocks');$('#content').innerHTML=head('Desbloqueios','Operações de desbloqueio com checklist, fotos e acompanhamento',`<button class="btn" onclick="unlockForm()">+ Novo desbloqueio</button>`)+table(d,[['id','#'],['unit','Unidade'],['brand','Marca'],['model','Modelo'],['imei','IMEI'],['kind','Operação'],['operator','Operador'],['status','Status',r=>badge(r.status)],['price','Valor',r=>money(r.price)]],r=>`<button class="btn ghost" onclick="unlockDetails(${r.id})">Abrir</button>`)},
 purchases:async()=>{let d=await list('purchases');$('#content').innerHTML=head('Compras / Vitrine','Compre aparelho, registre todos os gastos e calcule custo e margem',`<button class="btn" onclick="purchaseForm()">+ Comprar aparelho</button>`)+table(d,[['id','#'],['unit','Unidade'],['brand','Marca'],['model','Modelo'],['imei','IMEI'],['total_cost','Custo total',r=>money(r.total_cost)],['suggested_price','Venda sugerida',r=>money(r.suggested_price)],['expected_profit','Lucro previsto',r=>money(r.expected_profit)],['status','Status',r=>badge(r.status)]])},
 pdv:async()=>{$('#content').innerHTML=head('PDV','Venda rápida de produto, aparelho ou serviço com lançamento automático no financeiro',`<button class="btn" onclick="saleForm()">+ Nova venda</button>`)+`<div class="grid2"><section class="panel"><h2>Venda rápida</h2><p class="muted">O fechamento gera entrada no Financeiro e mantém a unidade selecionada.</p><button class="btn" onclick="saleForm()">Abrir caixa</button></section><section class="panel"><h2>Serviços por modelo</h2><p class="muted">Cadastre preços de tela, bateria, conector, câmera, tampa, software e outros em Precificação.</p><button class="btn dark" onclick="go('pricing')">Abrir tabela de preços</button></section></div>`},
 pricing:async()=>{let d=await list('models');$('#content').innerHTML=head('Precificação','Tabela por modelo, serviços, margem e garantia',`<button class="btn" onclick="modelForm()">+ Novo modelo</button>`)+table(d,[['id','#'],['brand','Marca'],['model','Modelo'],['service_prices','Serviços',r=>Object.keys(JSON.parse(r.service_prices||'{}')).join(', ')||'—'],['margin','Margem',r=>Number(r.margin||0)+'%'],['warranty','Garantia']])},
 quotes:async()=>{let d=await list('quotes');$('#content').innerHTML=head('Orçamentos','Crie orçamento, defina garantia, validade e envie um link público',`<button class="btn" onclick="quoteForm()">+ Novo orçamento</button>`)+table(d,[['number','Número'],['unit','Unidade'],['total','Total',r=>money(r.total)],['warranty_type','Garantia'],['valid_until','Válido até'],['status','Status',r=>badge(r.status)]],r=>`<button class="btn ghost" onclick="copyLink('${r.public_token}')">🔗 Copiar acompanhamento</button>`)},
 finance:async()=>{let d=await list('finance');let inc=d.filter(x=>x.type==='entrada').reduce((a,x)=>a+Number(x.amount),0),out=d.filter(x=>x.type==='saida').reduce((a,x)=>a+Number(x.amount),0);$('#content').innerHTML=head('Financeiro','Entradas e saídas automáticas por unidade',`<button class="btn" onclick="financeForm()">+ Lançamento</button>`)+`<div class="cards"><div class="metric"><div class="label">ENTRADAS</div><div class="value green">${money(inc)}</div></div><div class="metric"><div class="label">SAÍDAS</div><div class="value red">${money(out)}</div></div><div class="metric"><div class="label">SALDO</div><div class="value yellow">${money(inc-out)}</div></div></div><section class="panel" style="margin-top:15px">${table(d,[['id','#'],['unit','Unidade'],['type','Tipo'],['category','Categoria'],['description','Descrição'],['amount','Valor',r=>money(r.amount)],['due_date','Vencimento'],['created_at','Data']])}</section>`},
 inventory:async()=>{let d=await list('inventory');$('#content').innerHTML=head('Estoque','Peças, acessórios, fornecedores, mínimos e compatibilidade',`<button class="btn" onclick="inventoryForm()">+ Produto / peça</button><button class="btn dark" onclick="location.href='/api/export/inventory.csv'">CSV</button>`)+`<section class="panel">${table(d,[['code','Código'],['name','Nome'],['type','Tipo'],['category','Categoria'],['qty','Qtd'],['min_qty','Mín.',r=>Number(r.min_qty)],['cost','Custo',r=>money(r.cost)],['price','Venda',r=>money(r.price)],['supplier','Fornecedor'],['status','Status',r=>Number(r.qty)<=Number(r.min_qty)?'<span class="badge r">BAIXO</span>':'<span class="badge g">OK</span>']])}</section><section class="panel"><div class="panel-head"><h2>Compatibilidade de películas</h2><span class="badge y">Busca bidirecional</span></div><input class="input search" id="compat" placeholder="Ex.: iPhone 11, A32 4G, Redmi Note..." oninput="filterCompat()"><div id="compatres" style="margin-top:10px;color:#999">Digite um modelo para localizar compatibilidades cadastradas.</div></section>`},
 forgotten:async()=>{let d=await list('forgotten');$('#content').innerHTML=head('Aparelhos esquecidos','Bancada antiga, aparelhos sem retirada e possível identificação',`<button class="btn" onclick="forgottenForm()">+ Registrar aparelho</button>`)+table(d,[['id','#'],['unit','Unidade'],['brand','Marca'],['model','Modelo'],['imei','IMEI'],['possible_owner','Possível dono'],['status','Status',r=>badge(r.status)],['created_at','Data']])},
 contracts:async()=>{let d=await list('contracts');$('#content').innerHTML=head('Termos e garantias','Compra de usado e venda/garantia com assinatura digital',`<button class="btn" onclick="contractForm('compra_usado')">+ Termo compra de usado</button><button class="btn dark" onclick="contractForm('venda_garantia')">+ Termo venda/garantia</button>`)+table(d,[['id','#'],['unit','Unidade'],['type','Tipo'],['customer_name','Cliente'],['device_id','Aparelho'],['created_at','Data']])},
 users:async()=>{let d=await list('users');$('#content').innerHTML=head('Usuários e permissões','Acesso por perfil, unidade e permissões individuais',`<button class="btn" onclick="userForm()">+ Novo usuário</button>`)+table(d,[['id','#'],['name','Nome'],['email','E-mail'],['role','Perfil'],['unit','Unidade'],['active','Ativo']])},
 chat:async()=>{let d=await list('chat');$('#content').innerHTML=head('Chat entre unidades','Comunicação interna Lagos ↔ Magé')+`<section class="panel"><div class="timeline">${d.reverse().map(x=>`<div class="event"><b>${esc(x.user_name)}</b> <span class="badge y">${esc(x.unit)}</span><div>${esc(x.message)}</div><small class="muted">${esc(x.created_at)}</small></div>`).join('')||'<div class="muted">Nenhuma mensagem.</div>'}</div><form id="chatf" style="display:flex;gap:8px;margin-top:18px"><input class="input" name="message" style="flex:1" placeholder="Escreva para a equipe..." required><button class="btn">Enviar</button></form></section>`;$('#chatf').onsubmit=async e=>{e.preventDefault();let d=formValues(e.target);d.unit=UNIT;await api('/api/chat',{method:'POST',body:JSON.stringify(d)});render()}},
 admin:async()=>{$('#content').innerHTML=head('Administração','Backup, auditoria, integridade e manutenção do sistema')+`<div class="grid2"><section class="panel"><h2>Backup completo</h2><p class="muted">Exporta clientes, OS, aparelhos, estoque, financeiro, contratos, usuários, configurações, chat e demais dados em ZIP.</p><button class="btn" onclick="location.href='/api/export/backup'">⬇ Baixar backup ZIP</button></section><section class="panel"><h2>Saúde do sistema</h2><div class="kpi"><span>API</span><b class="green">ONLINE</b></div><div class="kpi"><span>Banco</span><b class="green">SQLite</b></div><div class="kpi"><span>Unidades</span><b>LAGOS + MAGÉ</b></div><div class="kpi"><span>Web</span><b class="green">PORT ${location.port||80}</b></div></section></div><section class="panel" style="margin-top:15px"><h2>Auditoria</h2>${table(await list('audit'),[['id','#'],['action','Ação'],['entity','Módulo'],['entity_id','ID'],['details','Detalhes'],['created_at','Data']])}</section>`},
 settings:async()=>{let s=await api('/api/settings');let fields=[['company_name','Nome da empresa'],['tagline','Subtítulo'],['phone','Telefone'],['instagram','Instagram'],['currency','Moeda'],['units','Unidades']];let html=head('Configurações','Dados da empresa, contato, identidade e parâmetros')+'<section class="panel"><form id="sf" class="formgrid">'+fields.map(x=>`<div class="field"><label>${x[1]}</label><input class="input" name="${x[0]}" value="${esc(s[x[0]]||'')}"></div>`).join('')+'<div class="field full"><button class="btn">Salvar configurações</button></div></form></section>';$('#content').innerHTML=html;$('#sf').onsubmit=async e=>{e.preventDefault();await api('/api/settings',{method:'POST',body:JSON.stringify(formValues(e.target))});toast('Configurações salvas')}}};
function formModal(title,body,onSubmit){$('#modal').innerHTML=`<div class="modalbox"><div class="modalhead"><h2>${title}</h2><button type="button" class="close" onclick="closeModal()">✕</button></div><div class="modalbody"><form id="modalForm" onsubmit="return false">${body}</form></div><div class="modalfoot"><button type="button" class="btn ghost" onclick="closeModal()">Cancelar</button><button type="button" class="btn" id="saveModal">Salvar</button></div></div>`;$('#modal').classList.add('show');$('#saveModal').onclick=onSubmit}
function closeModal(){$('#modal').classList.remove('show')}
function f(name,label,type='text',val='',full=false){return `<div class="field ${full?'full':''}"><label>${label}</label>${type==='textarea'?`<textarea class="textarea" name="${name}">${esc(val)}</textarea>`:type==='select'?`<select class="select" name="${name}">${val.map(x=>`<option>${x}</option>`).join('')}</select>`:`<input class="input" name="${name}" type="${type}" value="${esc(val)}">`}</div>`}
const checks=['Tela','Conector de carga','Bateria','Wi‑Fi','Bluetooth','Alto-falante','Microfone','Câmera frontal','Câmera traseira','Flash','Face ID / Biometria','Botões','Rede móvel','IMEI','Sem bloqueio de conta','Touch / toque','Carcaça / tampa','Aparelho liga'];
function checklist(name='checklist',selected={}){return `<div class="checkgrid">${checks.map((x,i)=>`<div class="check"><input type="checkbox" id="${name}${i}" name="${name}" value="${esc(x)}" ${selected[x]?'checked':''}><label for="${name}${i}">${esc(x)}</label></div>`).join('')}</div>`}
function collectChecks(form){let o={};form.querySelectorAll('input[name="checklist"]:checked').forEach(x=>o[x.value]=true);return o}
function photoBox(){return `<div class="field full"><label>Fotos do aparelho</label><div class="drop">📷 Adicione fotos da entrada, defeito, peças e aparelho finalizado.<input id="photos" type="file" accept="image/*" multiple></div><div id="preview" class="photos" style="margin-top:9px"></div></div>`}
async function readPhotos(){let files=[...($('#photos')?.files||[])];let arr=[];for(let file of files){let data=await new Promise(res=>{let r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(file)});arr.push(data)}return arr}
function serviceForm(kind){let title=kind==='desbloqueio'?'Nova Ordem de Serviço':'Nova Ordem de Serviço';formModal(title,`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'],false)}${f('customer_id','ID do cliente','number')}${f('device_id','ID do aparelho','number')}${f('technician','Técnico / operador')}${f('description','Serviço solicitado','text','',true)}${f('diagnosis','Diagnóstico','textarea','',true)}${f('price','Valor','number')} ${f('warranty','Garantia','text','90 dias')}${f('status','Status','select',['aberto','aguardando peça','em andamento','pronto','entregue','cancelado'])}<div class="field full"><label>Checklist técnico — marque o que foi conferido</label>${checklist()}</div>${photoBox()}${f('notes','Observações','textarea','',true)}</div>`,async()=>{let m=$('#modal'),photos=await readPhotos(),data={unit:m.querySelector('[name=unit]').value,customer_id:m.querySelector('[name=customer_id]').value,device_id:m.querySelector('[name=device_id]').value,kind,technician:m.querySelector('[name=technician]').value,description:m.querySelector('[name=description]').value,diagnosis:m.querySelector('[name=diagnosis]').value,price:m.querySelector('[name=price]').value,warranty:m.querySelector('[name=warranty]').value,status:m.querySelector('[name=status]').value,checklist:collectChecks(m),photos,notes:m.querySelector('[name=notes]').value};let r=await api('/api/services',{method:'POST',body:JSON.stringify(data)});toast('OS criada • link de acompanhamento disponível');closeModal();render()})}
function unlockForm(){formModal('Novo desbloqueio',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${f('customer_id','ID cliente','number')}${f('device_id','ID aparelho','number')}${f('operator','Operador')}${f('brand','Marca')}${f('model','Modelo')}${f('imei','IMEI')}${f('kind','Operação','select',['FRP / Conta','MDM','Desbloqueio de rede','Software','Outro'])}${f('price','Valor','number')}${f('status','Status','select',['aberto','em andamento','pronto','entregue','cancelado'])}<div class="field full"><label>Checklist do aparelho</label>${checklist()}</div>${photoBox()}${f('notes','Observações','textarea','',true)}</div>`,async()=>{let m=$('#modal');let data=formValues(m.querySelector('#modalForm'));data.unit=m.querySelector('[name=unit]').value;data.checklist=collectChecks(m);data.photos=await readPhotos();await api('/api/unlocks',{method:'POST',body:JSON.stringify(data)});closeModal();toast('Desbloqueio registrado');render()})}
function purchaseForm(){formModal('Compra de aparelho usado',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${f('customer_id','ID do vendedor/cliente','number')}${f('brand','Marca')}${f('model','Modelo')}${f('imei','IMEI')}${f('purchase_date','Data','date')}${f('amount','Valor pago','number')}${f('expenses','Gastos adicionais','number')}${f('freight','Frete / retirada','number')}${f('suggested_price','Preço sugerido de venda','number')}${f('status','Destino','select',['vitrine','em preparação','reservado'])}<div class="field full"><label>Checklist de compra e avaliação</label>${checklist()}</div>${photoBox()}${f('observations','Observações','textarea','',true)}</div>`,async()=>{let m=$('#modal'),data=formValues(m.querySelector('#modalForm'));data.unit=m.querySelector('[name=unit]').value;data.checklist=collectChecks(m);data.photos=await readPhotos();await api('/api/purchases',{method:'POST',body:JSON.stringify(data)});closeModal();toast('Compra registrada • aparelho enviado para vitrine');render()})}
