/* KV CELL OS PREMIUM V10 ULTIMATE FINAL */
function toast(s,type='info'){
  let t=document.getElementById('toast');
  if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}
  t.textContent=s||''; t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'),3200);
}
async function aiSafe(data){
  try{return await api('/api/ai/chat',{method:'POST',body:JSON.stringify(data)})}
  catch(e){return {ok:false,reply:e.message||'Não foi possível falar com a IA agora.'}}
}
